849	    private func canGroupItem(timelineItem: RoomTimelineItemProtocol, with otherTimelineItem: RoomTimelineItemProtocol) -> Bool {
850	        if timelineItem is CollapsibleTimelineItem || otherTimelineItem is CollapsibleTimelineItem {
851	            return false
852	        }
853	        
854	        guard let eventTimelineItem = timelineItem as? EventBasedTimelineItemProtocol,
855	              let otherEventTimelineItem = otherTimelineItem as? EventBasedTimelineItemProtocol else {
856	            return false
857	        }
858	        
859	        // State events aren't rendered as messages so shouldn't be grouped.
860	        if eventTimelineItem is StateRoomTimelineItem || otherEventTimelineItem is StateRoomTimelineItem {
861	            return false
862	        }
863	        
864	        return eventTimelineItem.sender == otherEventTimelineItem.sender
865	            && eventTimelineItem.properties.reactions.isEmpty // Reactions break the grouping.
866	            && otherEventTimelineItem.timestamp.timeIntervalSince(eventTimelineItem.timestamp) < 5 * 60 // As does the passage of time.
867	    }
