117	    
118	    func start(animated: Bool) {
119	        fatalError("This flow coordinator expect a route")
120	    }
121	    
122	    // swiftlint:disable:next cyclomatic_complexity
123	    func handleAppRoute(_ appRoute: AppRoute, animated: Bool) {
124	        guard stateMachine.state != .complete else {
125	            fatalError("This flow coordinator is `finished` ☠️")
126	        }
127	        
128	        switch appRoute {
129	        case .room(let roomID, let via):
130	            flowParameters.analytics.signpost.startTransaction(.openRoom)
131	            Task {
132	                await handleRoomRoute(roomID: roomID, via: via, animated: animated)
133	            }
134	        case .childRoom(let roomID, let via):
135	            if case .membersFlow = stateMachine.state, let membersFlowCoordinator {
136	                membersFlowCoordinator.handleAppRoute(appRoute, animated: animated)
137	            } else if case .presentingChild = stateMachine.state, let childRoomFlowCoordinator {
138	                childRoomFlowCoordinator.handleAppRoute(appRoute, animated: animated)
139	            } else if roomID != roomProxy.id {
140	                stateMachine.tryEvent(.startChildFlow(roomID: roomID, via: via, entryPoint: .room), userInfo: EventUserInfo(animated: animated))
141	            } else {
142	                MXLog.info("Ignoring presentation of the same room as a child of this one.")
143	            }
144	        case .roomDetails(let roomID):
145	            guard roomID == self.roomID else { fatalError("Navigation route doesn't belong to this room flow.") }
146	            
147	            Task {
148	                if roomProxy == nil {
149	                    guard case let .joined(roomProxy) = await userSession.clientProxy.roomForIdentifier(roomID) else {
150	                        return
151	                    }
152	                    
153	                    await storeAndSubscribeToRoomProxy(roomProxy)
154	                }
155	                
156	                stateMachine.tryEvent(.presentRoomDetails, userInfo: EventUserInfo(animated: animated))
157	            }
158	        case .roomMemberDetails(let userID):
159	            // Always assume this will be presented on the child, external permalinks to a user aren't for a room member.
160	            if case .membersFlow = stateMachine.state, let membersFlowCoordinator {
161	                membersFlowCoordinator.handleAppRoute(.roomMemberDetails(userID: userID), animated: animated)
162	            } else if case .presentingChild = stateMachine.state, let childRoomFlowCoordinator {
163	                childRoomFlowCoordinator.handleAppRoute(appRoute, animated: animated)
164	            } else {
165	                stateMachine.tryEvent(.startMembersFlow(entryPoint: .roomMember(userID: userID)), userInfo: EventUserInfo(animated: animated))
166	            }
167	        case .thread(let roomID, let threadRootEventID, let focusEventID):
168	            Task {
169	                let focusEvent: FocusEvent? = if let focusEventID {
170	                    .init(eventID: focusEventID, shouldSetPin: false)
171	                } else {
172	                    nil
173	                }
174	                await handleRoomRoute(roomID: roomID,
175	                                      via: [],
176	                                      presentationAction: .thread(rootEventID: threadRootEventID,
177	                                                                  focusEvent: focusEvent),
178	                                      animated: animated)
179	            }
180	        case .event(let eventID, let roomID, let via):
181	            Task {
182	                await handleRoomRoute(roomID: roomID,
183	                                      via: via,
184	                                      presentationAction: .eventFocus(.init(eventID: eventID, shouldSetPin: false)),
185	                                      animated: animated)
186	            }
187	        case .childEvent(let eventID, let roomID, let via):
188	            handleChildEventRoute(eventID: eventID, roomID: roomID, via: via, animated: animated)
189	        case .share(let payload):
190	            guard let roomID = payload.roomID, roomID == self.roomID else {
191	                fatalError("Navigation route doesn't belong to this room flow.")
192	            }
193	            
194	            Task {
195	                await handleRoomRoute(roomID: roomID,
196	                                      via: [],
197	                                      presentationAction: .share(payload),
198	                                      animated: animated)
199	            }
200	        case .roomAlias, .childRoomAlias, .eventOnRoomAlias, .childEventOnRoomAlias:
201	            break // These are converted to a room ID route one level above.
202	        case .accountProvisioningLink, .roomList, .userProfile, .call, .genericCallLink, .settings, .chatBackupSettings:
203	            break // These routes can't be handled.
204	        case .transferOwnership(let roomID):
205	            guard self.roomID == roomID else { fatalError("Navigation route doesn't belong to this room flow.") }
206	            
207	            Task {
208	                if roomProxy == nil {
209	                    guard case let .joined(roomProxy) = await userSession.clientProxy.roomForIdentifier(roomID) else {
210	                        return
211	                    }
212	                    
213	                    await storeAndSubscribeToRoomProxy(roomProxy)
214	                }
215	                
216	                stateMachine.tryEvent(.presentTransferOwnershipScreen)
217	            }
218	        }
219	    }
220	    
221	    private func handleChildEventRoute(eventID: String, roomID: String, via: [String], animated: Bool) {
222	        if case .membersFlow = stateMachine.state, let membersFlowCoordinator {
223	            membersFlowCoordinator.handleAppRoute(.childEvent(eventID: eventID, roomID: roomID, via: via), animated: animated)
224	        } else if case .presentingChild = stateMachine.state, let childRoomFlowCoordinator {
225	            childRoomFlowCoordinator.handleAppRoute(.childEvent(eventID: eventID, roomID: roomID, via: via), animated: animated)
226	        } else if roomID != roomProxy.id {
227	            stateMachine.tryEvent(.startChildFlow(roomID: roomID, via: via, entryPoint: .eventID(eventID)), userInfo: EventUserInfo(animated: animated))
228	        } else {
229	            showLoadingIndicator(delay: .seconds(0.5))
230	            Task {
231	                defer { hideLoadingIndicator() }
232	                switch await roomProxy.loadOrFetchEventDetails(for: eventID) {
233	                case .success(let event):
234	                    if flowParameters.appSettings.threadsEnabled, let threadRootEventID = event.threadRootEventId() {
235	                        if case .thread(threadRootEventID: threadRootEventID, _) = stateMachine.state, let threadCoordinator = childThreadScreenCoordinators.last {
236	                            threadCoordinator.focusOnEvent(eventID: eventID)
237	                        } else {
238	                            // If we are showing the room timeline, we want to focus the thread root.
239	                            if childThreadScreenCoordinators.isEmpty {
240	                                roomScreenCoordinator?.focusOnEvent(.init(eventID: threadRootEventID, shouldSetPin: false))
241	                            }
242	                            stateMachine.tryEvent(.presentThread(threadRootEventID: threadRootEventID, focusEventID: eventID))
243	                        }
244	                    } else if !childThreadScreenCoordinators.isEmpty {
245	                        // If we are showing a child thread and we are navigating to a non threaded event
246	                        // of the same room, we want to push the room on top of the thread.
247	                        stateMachine.tryEvent(.startChildFlow(roomID: roomID, via: via, entryPoint: .eventID(eventID)), userInfo: EventUserInfo(animated: animated))
248	                    } else {
249	                        roomScreenCoordinator?.focusOnEvent(.init(eventID: eventID, shouldSetPin: false))
250	                    }
251	                case .failure:
252	                    showErrorIndicator()
253	                }
254	            }
255	        }
256	    }
