258	    private func presentTransferOwnershipScreen() {
259	        let parameters = RoomChangeRolesScreenCoordinatorParameters(mode: .owner,
260	                                                                    roomProxy: roomProxy,
261	                                                                    mediaProvider: userSession.mediaProvider,
262	                                                                    userIndicatorController: flowParameters.userIndicatorController,
263	                                                                    analytics: flowParameters.analytics)
264	        let stackCoordinator = NavigationStackCoordinator()
265	        let coordinator = RoomChangeRolesScreenCoordinator(parameters: parameters)
266	        coordinator.actionsPublisher.sink { [weak self] action in
267	            guard let self else { return }
268	            switch action {
269	            case .complete:
270	                navigationStackCoordinator.setSheetCoordinator(nil)
271	            }
272	        }
273	        .store(in: &cancellables)
274	        
275	        stackCoordinator.setRootCoordinator(coordinator)
276	        navigationStackCoordinator.setSheetCoordinator(stackCoordinator) { [weak self] in
277	            self?.stateMachine.tryEvent(.dismissedTransferOwnershipScreen)
278	        }
279	    }
