281	    private func handleRoomRoute(roomID: String, via: [String], presentationAction: PresentationAction? = nil, animated: Bool) async {
282	        guard roomID == self.roomID else { fatalError("Navigation route doesn't belong to this room flow.") }
283	        
284	        showLoadingIndicator(delay: .seconds(0.5))
285	        defer { hideLoadingIndicator() }
286	        
287	        guard let room = await userSession.clientProxy.roomForIdentifier(roomID) else {
288	            stateMachine.tryEvent(.presentJoinRoomScreen(via: via), userInfo: EventUserInfo(animated: animated))
289	            return
290	        }
291	        
292	        switch room {
293	        case .joined(let roomProxy):
294	            if roomProxy.infoPublisher.value.isSpace {
295	                switch await userSession.clientProxy.spaceService.spaceRoomList(spaceID: roomProxy.id) {
296	                case .success(let spaceRoomListProxy):
297	                    actionsSubject.send(.continueWithSpaceFlow(spaceRoomListProxy))
298	                case .failure:
299	                    showErrorIndicator()
300	                    stateMachine.tryEvent(.dismissFlow)
301	                }
302	            } else {
303	                await storeAndSubscribeToRoomProxy(roomProxy)
304	                
305	                guard case let .eventFocus(focusEvent) = presentationAction else {
306	                    // If is not a focus event just handle the presentation action directly in `presentRoom`
307	                    stateMachine.tryEvent(.presentRoom(presentationAction: presentationAction), userInfo: EventUserInfo(animated: animated))
308	                    return
309	                }
310	                
311	                // Otherwise check if the focussed event exists to handle a possible error or theaded event.
312	                switch await roomProxy.loadOrFetchEventDetails(for: focusEvent.eventID) {
313	                case .success(let event):
314	                    if flowParameters.appSettings.threadsEnabled, let threadRootEventID = event.threadRootEventId() {
315	                        stateMachine.tryEvent(.presentRoom(presentationAction: .thread(rootEventID: threadRootEventID,
316	                                                                                       focusEvent: .init(eventID: focusEvent.eventID,
317	                                                                                                         shouldSetPin: focusEvent.shouldSetPin))),
318	                                              userInfo: EventUserInfo(animated: animated))
319	                    } else {
320	                        stateMachine.tryEvent(.presentRoom(presentationAction: presentationAction), userInfo: EventUserInfo(animated: animated))
321	                    }
322	                case .failure:
323	                    showErrorIndicator()
324	                    stateMachine.tryEvent(.presentRoom(presentationAction: nil), userInfo: EventUserInfo(animated: animated))
325	                }
326	            }
327	        default:
328	            stateMachine.tryEvent(.presentJoinRoomScreen(via: via), userInfo: EventUserInfo(animated: animated))
329	        }
330	    }
