9	import Combine
10	import SwiftUI
11	
12	typealias SpaceScreenViewModelType = StateStoreViewModelV2<SpaceScreenViewState, SpaceScreenViewAction>
13	
14	class SpaceScreenViewModel: SpaceScreenViewModelType, SpaceScreenViewModelProtocol {
15	    private let spaceRoomListProxy: SpaceRoomListProxyProtocol
16	    private let spaceServiceProxy: SpaceServiceProxyProtocol
17	    private let clientProxy: ClientProxyProtocol
18	    private let mediaProvider: MediaProviderProtocol
19	    private let userIndicatorController: UserIndicatorControllerProtocol
20	    
21	    private let actionsSubject: PassthroughSubject<SpaceScreenViewModelAction, Never> = .init()
22	    var actionsPublisher: AnyPublisher<SpaceScreenViewModelAction, Never> {
23	        actionsSubject.eraseToAnyPublisher()
24	    }
25	
26	    init(spaceRoomListProxy: SpaceRoomListProxyProtocol,
27	         spaceServiceProxy: SpaceServiceProxyProtocol,
28	         selectedSpaceRoomPublisher: CurrentValuePublisher<String?, Never>,
29	         userSession: UserSessionProtocol,
30	         userIndicatorController: UserIndicatorControllerProtocol) {
31	        self.spaceRoomListProxy = spaceRoomListProxy
32	        self.spaceServiceProxy = spaceServiceProxy
33	        clientProxy = userSession.clientProxy
34	        mediaProvider = userSession.mediaProvider
35	        self.userIndicatorController = userIndicatorController
36	        
37	        super.init(initialViewState: SpaceScreenViewState(space: spaceRoomListProxy.spaceServiceRoomPublisher.value,
38	                                                          rooms: spaceRoomListProxy.spaceRoomsPublisher.value,
39	                                                          selectedSpaceRoomID: selectedSpaceRoomPublisher.value),
40	                   mediaProvider: userSession.mediaProvider)
41	        
42	        spaceRoomListProxy.spaceServiceRoomPublisher
43	            .receive(on: DispatchQueue.main)
44	            .weakAssign(to: \.state.space, on: self)
45	            .store(in: &cancellables)
46	        
47	        spaceRoomListProxy.spaceRoomsPublisher
48	            .receive(on: DispatchQueue.main)
49	            .weakAssign(to: \.state.rooms, on: self)
50	            .store(in: &cancellables)
51	        
52	        // As the server is slow, we just let the screen automatically paginate everything in. We can
53	        // switch this to use the scroll position once Synapse receives some performance improvements.
54	        spaceRoomListProxy.paginationStatePublisher
55	            .receive(on: DispatchQueue.main)
56	            .sink { [weak self] paginationState in
57	                guard let self else { return }
58	                
59	                switch paginationState {
60	                case .idle(endReached: false):
61	                    state.paginationState = .idle
62	                    Task { await spaceRoomListProxy.paginate() }
63	                case .idle(endReached: true):
64	                    state.paginationState = .endReached
65	                case .loading:
66	                    state.paginationState = .paginating
67	                }
68	            }
69	            .store(in: &cancellables)
70	        
71	        selectedSpaceRoomPublisher
72	            .weakAssign(to: \.state.selectedSpaceRoomID, on: self)
73	            .store(in: &cancellables)
74	        
75	        Task {
76	            if case let .joined(roomProxy) = await userSession.clientProxy.roomForIdentifier(spaceRoomListProxy.id) {
77	                // Required to listen for membership updates in the members flow
78	                await roomProxy.subscribeForUpdates()
79	                state.roomProxy = roomProxy
80	                if case let .success(permalinkURL) = await roomProxy.matrixToPermalink() {
81	                    state.permalink = permalinkURL
82	                }
83	                
84	                roomProxy.infoPublisher
85	                    .sink { [weak self] roomInfo in
86	                        guard let self else { return }
87	                        guard let powerLevels = roomInfo.powerLevels else {
88	                            state.canEditBaseInfo = false
89	                            state.canEditRolesAndPermissions = false
90	                            state.canEditSecurityAndPrivacy = false
91	                            state.canEditChildren = false
92	                            return
93	                        }
94	                        state.canEditBaseInfo = powerLevels.canOwnUserEditBaseInfo()
95	                        state.canEditRolesAndPermissions = powerLevels.canOwnUserEditRolesAndPermissions()
96	                        state.canEditSecurityAndPrivacy = powerLevels.canOwnUserEditSecurityAndPrivacy(isSpace: roomInfo.isSpace,
97	                                                                                                       joinRule: roomInfo.joinRule)
98	                        state.canEditChildren = powerLevels.canOwnUser(sendStateEvent: .spaceChild)
99	                    }
100	                    .store(in: &cancellables)
101	            }
102	        }
103	    }
104	    
105	    // MARK: - Public
106	    
107	    override func process(viewAction: SpaceScreenViewAction) {
108	        MXLog.info("View model: received view action: \(viewAction)")
109	        
110	        switch viewAction {
111	        case .spaceAction(.select(let spaceServiceRoom)) where state.editMode == .inactive:
112	            if spaceServiceRoom.isSpace {
113	                if spaceServiceRoom.state != .joined {
114	                    actionsSubject.send(.selectUnjoinedSpace(spaceServiceRoom))
115	                } else {
116	                    Task { await selectSpace(spaceServiceRoom) }
117	                }
118	            } else {
119	                // No need to check the join state, the room flow will show an appropriately configured join screen if needed.
120	                actionsSubject.send(.selectRoom(roomID: spaceServiceRoom.id))
121	            }
122	        case .spaceAction(.select(let spaceServiceRoom)): // isEditModeActive == true
123	            withTransaction(\.disablesAnimations, true) { // The button adds an unwanted animation.
124	                if state.editModeSelectedIDs.contains(spaceServiceRoom.id) {
125	                    state.editModeSelectedIDs.remove(spaceServiceRoom.id)
126	                } else {
127	                    state.editModeSelectedIDs.insert(spaceServiceRoom.id)
128	                }
129	            }
130	        case .spaceAction(.join(let spaceServiceRoom)):
131	            Task { await join(spaceServiceRoom) }
132	        case .leaveSpace:
133	            Task { await showLeaveSpaceConfirmation() }
134	        case .displayMembers(let roomProxy):
135	            actionsSubject.send(.displayMembers(roomProxy: roomProxy))
136	        case .spaceSettings(let roomProxy):
137	            actionsSubject.send(.displaySpaceSettings(roomProxy: roomProxy))
138	        case .addExistingRooms:
139	            actionsSubject.send(.addExistingChildren)
140	        case .manageChildren:
141	            withAnimation(.easeOut(duration: 0.25).disabledDuringTests()) {
142	                state.editMode = .transient
143	            }
144	        case .removeSelectedChildren:
145	            state.bindings.isPresentingRemoveChildrenConfirmation = true
146	        case .confirmRemoveSelectedChildren:
147	            Task { await removeSelectedChildren() }
148	        case .finishManagingChildren:
149	            withAnimation(.easeOut(duration: 0.25).disabledDuringTests()) {
150	                state.editMode = .inactive
151	                state.editModeRemovedIDs = []
152	            } completion: {
153	                self.state.editModeSelectedIDs.removeAll()
154	            }
155	        case .createChildRoom:
156	            Task { await createChildRoom() }
157	        }
158	    }
159	    
160	    func stop() {
161	        // If we pop this screen with running join operations, we don't want them to do anything.
162	        state.joiningRoomIDs.removeAll()
163	    }
164	    
165	    func resetRoomList() {
166	        Task { await spaceRoomListProxy.resetAndWaitForFullReload(timeout: .seconds(10)) }
167	    }
168	    
169	    // MARK: - Private
170	    
171	    private func createChildRoom() async {
172	        switch await spaceServiceProxy.spaceForIdentifier(spaceID: spaceRoomListProxy.id) {
173	        case .success(.some(let space)):
174	            actionsSubject.send(.displayCreateChildRoomFlow(space: space))
175	        default:
176	            MXLog.error("Unable to create child room: space not found")
177	            userIndicatorController.submitIndicator(.init(title: L10n.errorUnknown))
178	        }
179	    }
180	    
181	    private func join(_ spaceServiceRoom: SpaceServiceRoom) async {
182	        state.joiningRoomIDs.insert(spaceServiceRoom.id)
183	        defer { state.joiningRoomIDs.remove(spaceServiceRoom.id) }
184	        
185	        guard case .success = await clientProxy.joinRoom(spaceServiceRoom.id, via: spaceServiceRoom.via) else {
186	            showFailureIndicator()
187	            return
188	        }
189	        
190	        // We don't want to show the space room after joining it this way 🤷‍♂️
191	    }
192	    
193	    private func selectSpace(_ spaceServiceRoom: SpaceServiceRoom) async {
194	        switch await spaceServiceProxy.spaceRoomList(spaceID: spaceServiceRoom.id) {
195	        case .success(let spaceRoomListProxy):
196	            actionsSubject.send(.selectSpace(spaceRoomListProxy))
197	        case .failure(let error):
198	            MXLog.error("Unable to select space: \(error)")
199	            showFailureIndicator()
200	        }
